/** Shape of api.json (generated by nomad_sdk.playground.reference from docstrings + signatures). */

export interface ParamDoc {
  name: string;
  type: string | null;
  default: string | null;
  kind: string | null;
  description: string;
}

export interface TypedDoc {
  type: string | null;
  description: string;
}

export interface FunctionDoc {
  kind: 'function' | 'property';
  name: string;
  path: string;
  signature: string;
  returns_type: string | null;
  labels: string[];
  description: string;
  parameters: ParamDoc[];
  returns: TypedDoc[];
  raises: TypedDoc[];
}

export interface AttributeDoc {
  kind: 'attribute';
  name: string;
  path: string;
  type: string | null;
  default: string | null;
  description: string;
}

export type MemberDoc = FunctionDoc | AttributeDoc;

export interface ClassDoc {
  kind: 'class' | 'exception';
  name: string;
  path: string;
  signature: string;
  bases: string[];
  description: string;
  parameters: ParamDoc[];
  raises: TypedDoc[];
  members: MemberDoc[];
}

export type ItemDoc = ClassDoc | FunctionDoc;

export interface ModuleDoc {
  kind: 'module';
  name: string;
  path: string;
  description: string;
  members: ItemDoc[];
}

export interface ApiReference {
  packages: ModuleDoc[];
}

export type AnyDoc = ModuleDoc | ItemDoc | MemberDoc;
